// === Nur PDF-Anhänge, je Anhang ein Item ===
// Vereinheitlicht die Binärdaten auf den Namen "data",
// damit der nächste Node einen festen Feldnamen hat.
const out = [];

for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b    = bin[key];
    const name = String(b.fileName || '').toLowerCase();
    const typ  = String(b.mimeType || '').toLowerCase();
    if (typ !== 'application/pdf' && !name.endsWith('.pdf')) continue;

    out.push({
      json: {
        absender:  item.json.from    || '',
        betreff:   item.json.subject || '',
        empfangen: item.json.date    || new Date().toISOString(),
        dateiname: b.fileName || 'unbenannt.pdf'
      },
      binary: { data: b }
    });
  }
}

if (out.length === 0) console.log('Keine PDF-Anhänge in dieser Mail.');
return out;

// === Felder aus dem Rechnungstext erkennen ===
// Reine Textarbeit, kein externer Dienst, keine Cloud.
// Erwartet den PDF-Text im Feld "text" (liefert "Aus Datei extrahieren").

const deZahl = s => {
  if (!s) return null;
  let t = String(s).trim().replace(/[^\d.,-]/g, '');
  if (t.includes(',') && t.includes('.')) t = t.replace(/\./g, '').replace(',', '.');
  else if (t.includes(',')) t = t.replace(',', '.');
  const n = Number(t);
  return isNaN(n) ? null : n;
};

const isoDatum = s => {
  if (!s) return null;
  const a = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (a) return `${a[1]}-${a[2]}-${a[3]}`;
  const b = s.match(/(\d{1,2})[.\/](\d{1,2})[.\/](\d{2,4})/);
  if (!b) return null;
  let [, t, m, j] = b;
  if (j.length === 2) j = (Number(j) > 70 ? '19' : '20') + j;
  return `${j}-${String(m).padStart(2,'0')}-${String(t).padStart(2,'0')}`;
};

const out = [];

for (const item of $input.all()) {
  const roh   = String(item.json.text || '');
  const text  = roh.replace(/\r/g, '');
  const flach = text.replace(/\n/g, ' ');

  // --- Rechnungsnummer ---
  const mNr = flach.match(/(?:Rechnung(?:s)?[-\s]?(?:Nr\.?|Nummer)|Invoice\s*(?:No\.?|Number)|Beleg(?:nr|nummer))\s*[:.]?\s*([A-Za-z0-9][A-Za-z0-9\/\-\.]{2,24})/i);
  const rechnungsnummer = mNr ? mNr[1].replace(/[.,;]$/, '') : null;

  // --- Datum: bevorzugt das neben "Rechnungsdatum" ---
  const mDat = flach.match(/(?:Rechnungsdatum|Belegdatum|Datum|Invoice date)\s*[:.]?\s*([0-9]{1,2}[.\/][0-9]{1,2}[.\/][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})/i);
  const datum = isoDatum(mDat ? mDat[1] : flach);

  // --- Bruttobetrag ---
  const mBetrag = flach.match(/(?:Gesamtbetrag|Rechnungsbetrag|Gesamtsumme|Endbetrag|Zu zahlen(?:der Betrag)?|Brutto(?:betrag)?|Total(?:\s*amount)?)\D{0,20}([0-9][0-9.\s]*,[0-9]{2}|[0-9][0-9,\s]*\.[0-9]{2})/i);
  let betrag = mBetrag ? deZahl(mBetrag[1]) : null;

  // Fallback: größter Betrag mit zwei Nachkommastellen im Text
  if (betrag === null) {
    const alle = (flach.match(/[0-9][0-9.\s]*,[0-9]{2}|[0-9][0-9,\s]*\.[0-9]{2}/g) || [])
      .map(deZahl).filter(n => n !== null);
    if (alle.length) betrag = Math.max(...alle);
  }

  // --- Währung, Steuersatz, IBAN ---
  const mWaehrung = flach.match(/\b(EUR|USD|CHF|GBP)\b|(€)/);
  const waehrung  = mWaehrung ? (mWaehrung[1] || 'EUR') : 'EUR';

  const mUst = flach.match(/(\d{1,2}(?:[.,]\d)?)\s*%\s*(?:USt|MwSt|Umsatzsteuer|VAT)?/i);
  const steuersatz = mUst ? deZahl(mUst[1]) : null;

  const mIban = flach.match(/\b([A-Z]{2}\d{2}(?:\s?[A-Z0-9]{4}){2,7}[A-Z0-9]{0,4})\b/);
  const iban = mIban ? mIban[1].replace(/\s/g, '') : null;

  const mUstId = flach.match(/\b(DE\s?\d{9}|[A-Z]{2}\s?[A-Z0-9]{8,12})\b(?=[^A-Z0-9]|$)/);
  const ustId = mUstId && /USt|VAT|Steuernummer/i.test(flach) ? mUstId[1].replace(/\s/g, '') : null;

  // --- Lieferant: erste brauchbare Zeile des Dokuments ---
  const zeilen = text.split('\n').map(z => z.trim()).filter(Boolean);
  const lieferant = (zeilen.find(z =>
    z.length > 3 && z.length < 60 &&
    !/^(rechnung|invoice|seite|page|datum|kunde)/i.test(z) &&
    /[A-Za-zÄÖÜäöüß]/.test(z)
  ) || '').slice(0, 60) || null;

  // --- Wie sicher ist das? ---
  const gefunden = [rechnungsnummer, datum, betrag, lieferant].filter(v => v !== null && v !== '').length;
  const pruefen  = gefunden < 3 || betrag === null;

  out.push({ json: {
    lieferant, rechnungsnummer, datum,
    betrag_brutto: betrag, waehrung, steuersatz, iban, ust_id: ustId,
    dateiname: item.json.dateiname || '',
    absender:  item.json.absender  || '',
    betreff:   item.json.betreff   || '',
    empfangen: item.json.empfangen || '',
    felder_gefunden: gefunden,
    pruefen,
    erfasst_am: new Date().toISOString()
  }});
}

return out;
